/**
 * The door contract test. The fixtures are the runtime door's own responses
 * (door.json, generated by running door.js at the commit in its `$source`;
 * dev-runtime-2026-10-30.json, captured from the Dev runtime). This test holds
 * the one contract module (doorContract.ts) against them in two ways:
 *
 *   - at type level (tsc, run by `pnpm test`): the fixtures must satisfy the
 *     contract types (see __fixtures__/door/index.ts), and an item carrying a
 *     `role` or `agentSponsor` must NOT be a DoorItem (@ts-expect-error below
 *     fails tsc if the contract ever starts to accept one);
 *   - at run time (jest): every key the door sent is a key the contract
 *     declares, and every key the contract requires is sent.
 */
import {describe, expect, it} from '@jest/globals'

import {
  DEV_RUNTIME,
  DOOR,
  DOOR_SOURCE_COMMIT,
  doorItem,
} from '#/lib/communities/__fixtures__/door'
import {
  DOOR_ITEM_KEYS,
  type DoorItem,
  type DoorTimelinePage,
  isDoorItem,
} from '#/lib/communities/doorContract'

const REQUIRED_ITEM_KEYS = ['id', 'parentId', 'authorId', 'text', 'createdAt']
const COMMUNITY_KEYS = [
  'id',
  'name',
  'description',
  'accent',
  'wording_version',
  'agent',
  'agent_error',
  'viewer_is_admin',
]

/** Problems with one item against the contract; [] when it conforms. */
function itemProblems(v: unknown): string[] {
  if (typeof v !== 'object' || v === null) return ['not an object']
  const it = v as Record<string, unknown>
  const known = new Set<string>(DOOR_ITEM_KEYS)
  const problems = Object.keys(it)
    .filter(k => !known.has(k))
    .map(k => `unexpected key "${k}"`)
  for (const k of REQUIRED_ITEM_KEYS) {
    if (!(k in it)) problems.push(`missing "${k}"`)
  }
  if (it.author !== undefined) {
    const a = it.author as Record<string, unknown>
    const extra = Object.keys(a).filter(k => k !== 'did' && k !== 'is_agent')
    problems.push(...extra.map(k => `unexpected author key "${k}"`))
  }
  return problems
}

function pageProblems(v: unknown): string[] {
  if (typeof v !== 'object' || v === null) return ['not an object']
  const p = v as Record<string, unknown>
  const extra = Object.keys(p).filter(k => k !== 'items' && k !== 'cursor')
  const problems = extra.map(k => `unexpected page key "${k}"`)
  if (!Array.isArray(p.items)) return [...problems, 'items is not an array']
  return [...problems, ...p.items.flatMap(itemProblems)]
}

describe('door contract fixtures', () => {
  it('note the runtime commit they were generated from', () => {
    expect(DOOR_SOURCE_COMMIT).toMatch(/^[0-9a-f]{40}$/)
    expect(DOOR.$source.module).toBe('src/communities/door.js')
  })

  it('timeline pages are {items, cursor}, never {posts}', () => {
    for (const page of [DOOR.timeline, DEV_RUNTIME.timeline]) {
      expect(pageProblems(page)).toEqual([])
      expect(page).not.toHaveProperty('posts')
      expect(page.cursor).toBeNull()
    }
    expect(DOOR.timeline.items.length).toBeGreaterThan(0)
    expect(DEV_RUNTIME.timeline.items.length).toBeGreaterThan(0)
  })

  it('every item from every route matches the contract', () => {
    const items: unknown[] = [
      ...DOOR.timeline.items,
      ...DOOR.export.items,
      DOOR.post.item,
      DOOR.reply.item,
      ...DEV_RUNTIME.timeline.items,
    ]
    for (const it of items) {
      expect(itemProblems(it)).toEqual([])
      expect(isDoorItem(it)).toBe(true)
    }
  })

  it('items carry text and authorId, and no role, agentSponsor or body', () => {
    for (const it of [
      ...DOOR.timeline.items,
      ...DEV_RUNTIME.timeline.items,
    ] as Record<string, unknown>[]) {
      expect(typeof it.text).toBe('string')
      expect(typeof it.authorId).toBe('string')
      expect(it).not.toHaveProperty('role')
      expect(it).not.toHaveProperty('agentSponsor')
      expect(it).not.toHaveProperty('body')
    }
  })

  it('covers the agent and legacy author shapes', () => {
    const agent = doorItem('agent')
    expect(agent.author).toEqual({did: expect.any(String), is_agent: true})
    expect(agent.sources?.length).toBeGreaterThan(0)
    expect(agent.no_source).toBe(false)
    expect(doorItem('legacy').author).toEqual({did: null, is_agent: false})
  })

  it('communities carry only publicConfig keys (no role, no agentSponsor)', () => {
    const communities = [
      ...DOOR.list.communities,
      ...DOOR.listAsMember.communities,
      DOOR.community.community,
      ...DEV_RUNTIME.list.communities,
      DEV_RUNTIME.home.community,
    ]
    for (const c of communities) {
      expect(
        Object.keys(c).filter(k => !COMMUNITY_KEYS.includes(k)),
      ).toEqual([])
    }
  })
})

describe('door contract rejects drift', () => {
  it('flags a role on an item', () => {
    const real = doorItem('post')
    expect(itemProblems({...real, role: 'member'})).toEqual([
      'unexpected key "role"',
    ])
    expect(itemProblems({...real, agentSponsor: 'did:plc:x'})).toEqual([
      'unexpected key "agentSponsor"',
    ])
  })

  it('flags the old invented shape', () => {
    const invented = {
      posts: [
        {
          id: 'p1',
          author: {displayName: 'Steve', is_agent: false},
          body: 'hi',
          createdAt: '2026-10-28T10:00:00.000Z',
        },
      ],
    }
    expect(pageProblems(invented)).toContain('unexpected page key "posts"')
    expect(itemProblems(invented.posts[0])).toEqual(
      expect.arrayContaining([
        'unexpected key "body"',
        'missing "text"',
        'missing "authorId"',
        'unexpected author key "displayName"',
      ]),
    )
    expect(isDoorItem(invented.posts[0])).toBe(false)
  })

  it('the type rejects a role on an item (checked by tsc)', () => {
    const real = doorItem('post')
    const withRole: DoorItem = {
      ...real,
      // @ts-expect-error the door never sends a role on an item
      role: 'member',
    }
    const withSponsor: DoorItem = {
      ...real,
      // @ts-expect-error the door never sends agentSponsor on an item
      agentSponsor: 'did:plc:x',
    }
    // @ts-expect-error a timeline page is {items, cursor}, not {posts}
    const postsPage: DoorTimelinePage = {posts: [real], cursor: null}
    expect(withRole).toHaveProperty('role')
    expect(withSponsor).toHaveProperty('agentSponsor')
    expect(postsPage).toHaveProperty('posts')
  })
})
